pageNum = Number(chapterList.page.length);
chapterPosNext = (chapterIndex + 1 == chapterList.chapter.length ? chapterList.page[-1] : Number(chapterList.chapter[chapterIndex + 1].pos));

for (i = 0; i < pageNum; i++) {
    if (chapterPosNext < chapterList.page[i]) {
        break;
    } else if (chapterPos <= chapterList.page[i]) {
        url = 'https://kanshuv.com/api/changkan/portal/novel/getReaderContent?num=50&pageStart=' + chapterList.page[i] + '&id=' + java.get("bid") + '&headers={"Content-Type":"application/x-www-form-urlencoded"}';
        pageContent += JSON.parse(java.ajax(url)).result.content;
    }
}

a = mergeStrings(content, pageContent);

if(chapterIndex + 1 == chapterList.chapter.length){
	result=a;
	}
else{
match = a.slice(50).match(/第\s*([一二三四五六七八九十百千万]+|\d+)\s*章.*$/);
if (match) {
